/* CCShalom Escalas • No private data in localStorage, caches or offline queues. */
(() => {
  'use strict';
  const root=document.getElementById('ccs-app');
  if (!root || typeof CCS_CONFIG==='undefined') return;
  const content=root.querySelector('#ccs-content'), nav=root.querySelector('.ccs-nav'), dialog=root.querySelector('#ccs-dialog'), message=root.querySelector('#ccs-message');
  if(!content||!nav||!dialog||!message)return;
  let state=null, view='home', busy=false, filter={q:'',team:'',period:'future'}, lastFocus=null, manageSection='dashboard', mineSection='assigned', previewDraft=null, teamMemberDraft=null;
  let peopleQuery='', peoplePage=1, openedOccurrence=0, deepLinkHandled=false;
  const dashboardFilter={period:'future',month:'',department:'',status:'published'};
  const peoplePageSize=10;
  const normalizeName=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim();
  const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=v=>Number(v), same=(a,b)=>num(a)===num(b);
  const user=id=>state.users.find(u=>same(u.id,id))?.name||'Usuário removido';
  const statuses={available:'Vaga disponível',pending:'Aguardando resposta',confirmed:'Confirmado',declined:'Aguardando substituto',cancelled:'Cancelado',accepted:'Substituição aceita'};
  const icon={home:'⌂',mine:'▦',teams:'♧',manage:'⚙',profile:'○'};
  const active=u=>u.active&&u.can_serve!==false;
  const manageable=()=>!!state.me.can_manage;
  const plansAllowed=()=>!!state.me.can_manage;
  const modeLabel=m=>m==='functions'?'Vagas por função':m==='open'?'Vaga aberta · 1 pessoa':'Convocar equipe inteira';
  const openEvents=()=>eventViews.openEvents();
  const stamp=v=>{if(!v)return '';const [d,t]=v.split(' '),[y,m,day]=d.split('-');return `${day}/${m}/${y} · ${t.slice(0,5)}`;};
  const day=v=>{const [,m,d]=v.slice(0,10).split('-');return {d,m:['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'][num(m)-1]};};
  const badge=(s,label)=>`<span class="ccs-badge ${e(s)}">${e(label||statuses[s]||s)}</span>`;
  const button=(label,action,id='',cls='secondary')=>`<button type="button" class="ccs-button ${cls}" data-action="${e(action)}" data-id="${e(id)}">${e(label)}</button>`;
  const options=(users,selected=0,empty='Selecione')=>`<option value="">${e(empty)}</option>`+users.map(u=>`<option value="${num(u.id)}" ${same(u.id,selected)?'selected':''}>${e(u.name)}</option>`).join('');
  const input=(label,name,type='text',value='',required=true,extra='')=>`<label class="ccs-field">${e(label)}<input name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} ${extra}></label>`;
  const select=(label,name,html)=>`<label class="ccs-field">${e(label)}<select name="${name}">${html}</select></label>`;
  const heading=(eyebrow,title,desc='')=>`<div class="ccs-section-heading"><span class="ccs-eyebrow">${e(eyebrow)}</span><h1 tabindex="-1">${e(title)}</h1>${desc?`<p>${e(desc)}</p>`:''}</div>`;
  const eventViews=window.CCS_EVENT_VIEWS({getState:()=>state,e,num,same,button,badge,modeLabel,day,stamp,user,content,root,dialog,heading,empty,input,select,form,open,notify,api,load,filter,dashboardFilter,managementTabs,getMineSection:()=>mineSection,setOpened:id=>openedOccurrence=id});
  const appButtons=()=>Array.from(root.querySelectorAll('button')).filter(b=>!b.closest('[data-ppush]'));
  function notify(text,error=false){message.textContent=text;message.className=error?'ccs-alert error':'ccs-alert';message.setAttribute('role',error?'alert':'status');}
  async function api(path,body){
    if(!navigator.onLine)throw new Error('Você está sem conexão. Conecte-se para consultar ou salvar suas escalas.');
    const response=await fetch(CCS_CONFIG.api+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:{'X-WP-Nonce':CCS_CONFIG.nonce,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});
    let data;try{data=await response.json();}catch{throw new Error('O servidor não retornou uma resposta válida. Tente atualizar a página.');}
    if(!response.ok)throw new Error(data.message||'Não foi possível concluir. Entre novamente e tente outra vez.');
    return data;
  }
  async function load(){
    state=await api('state');updateBell();render();
    if(!deepLinkHandled){deepLinkHandled=true;const id=num(new URL(location.href).searchParams.get('ccs_event'));if(id){eventViews.details(id);return;}}
    biometricPrompt();
  }
  async function save(data){
    if(busy)return;
    const restore=openedOccurrence;busy=true;appButtons().forEach(b=>b.disabled=true);
    try{const result=await api('action',data);close();notify(result.message);try{await load();const id=result.occurrence_ids?.[0]||restore;if(id&&state.occurrences.some(o=>same(o.id,id)))eventViews.details(id);}catch{notify('Alteração salva, mas a lista não pôde ser atualizada. Atualize a página para consultar.',true);}}
    catch(err){notify(err.message,true);const box=dialog.querySelector('.ccs-form-error');if(box){box.textContent=err.message;box.focus();}}
    finally{busy=false;appButtons().forEach(b=>b.disabled=false);if(view==='manage'&&manageSection==='schedules')renderPeople();}
  }
  function open(title,html){dialog.classList?.remove('ccs-event-dialog');dialog.classList?.toggle('ccs-notification-dialog',title==='Notificações');lastFocus=document.activeElement;dialog.innerHTML=`<div class="ccs-dialog-head"><h2 id="ccs-dialog-title">${e(title)}</h2><button class="ccs-close" type="button" data-action="close" aria-label="Fechar">×</button></div>${html}`;if(!dialog.open)dialog.showModal();dialog.querySelector('input, select, button')?.focus();}
  function close(){dialog.close();openedOccurrence=0;lastFocus?.focus();}
  function form(action,html,id=0,submit='Salvar'){const kind=({department:'department',team:'team',user:'user',celebration:'celebration',function:'function',edit_schedule:'schedule'})[action];const remove=num(id)&&kind?`<div class="ccs-delete-zone">${button('Excluir este cadastro','delete_item',kind+':'+id,'danger')}</div>`:'';return `<form data-form="${action}"><input type="hidden" name="id" value="${num(id)}"><div class="ccs-form-error" role="alert" tabindex="-1"></div>${html}<div class="ccs-form-actions"><button class="ccs-button" type="submit">${e(submit)}</button>${button('Voltar','close')}</div>${remove}</form>`;}
  function members(event){return state.slots.filter(s=>same(s.event_id,event.id));}
  function mySlot(event){return members(event).find(s=>same(s.assigned_id,state.me.id));}
  function eventCard(event){
    const ds=day(event.starts),slots=members(event),confirmed=slots.filter(s=>s.status==='confirmed').length,mine=mySlot(event);
    return `<article class="ccs-event"><div class="ccs-date"><strong>${ds.d}</strong><span>${ds.m}</span></div><div class="ccs-event-body"><span class="ccs-eyebrow">${e(event.team_name)}</span><h3>${e(event.title)}</h3><p>${e(event.starts.slice(11,16))}–${e(event.ends.slice(11,16))} · Chegada ${e(event.arrival.slice(11,16))}</p>${event.location?`<p>${e(event.location)}</p>`:''}<div class="ccs-badges">${event.status==='cancelled'?badge('cancelled'):mine?badge(mine.status):['open','functions'].includes(event.mode)&&slots.some(s=>s.status==='available')?badge('available'):badge('neutral',`${confirmed}/${slots.length} confirmados`)}</div></div><button class="ccs-card-link" data-action="event" data-id="${num(event.id)}" aria-label="Ver ${e(event.title)} de ${e(stamp(event.starts))}">Ver escala <span aria-hidden="true">→</span></button></article>`;
  }
  function empty(text){return `<div class="ccs-empty"><span aria-hidden="true">✦</span><p>${e(text)}</p></div>`;}
  function render(){
    eventViews.parkPush();
    nav.innerHTML=[['home','Início'],...(state.me.secretary?[]:[['mine','Minhas escalas']]),['teams','Equipes'],...(manageable()?[['manage','Gestão']]:[]),['profile','Perfil']].map(([v,label])=>`<button type="button" data-view="${v}" ${view===v?'aria-current="page"':''}><span class="ccs-nav-icon" aria-hidden="true">${icon[v]}</span><span>${label}</span></button>`).join('');
    if(view==='home')home();else if(view==='mine')mine();else if(view==='teams')teams();else if(view==='manage')manage();else profile();
  }
  function home(){eventViews.home();}
  function inviteCard(i){
    const s=state.slots.find(s=>same(s.id,i.slot_id)),ev=state.events.find(ev=>same(ev.id,s?.event_id));
    if(!ev||ev.status!=='published'||ev.starts<=state.now)return '';
    return `<article class="ccs-card ccs-invitation"><span class="ccs-eyebrow">CONVITE DE SUBSTITUIÇÃO</span><h3>${e(user(i.from_id))} convidou você</h3><p>${e(ev.title)} · ${e(ev.team_name)}</p>${s.function_name?`<p>Função: ${e(s.function_name)}</p>`:''}<p>${e(stamp(ev.starts))} · Chegada ${e(ev.arrival.slice(11,16))}</p><div class="ccs-actions">${button('Aceitar e confirmar','accept',i.id,'')}${button('Não posso','reject',i.id)}</div></article>`;
  }
  function mine(){
    content.innerHTML=heading('SUA PARTICIPAÇÃO','Minhas escalas','Confirme presença, escolha uma vaga ou convide um substituto.')+`<div class="ccs-tabs"><button type="button" data-action="mine_assigned" aria-pressed="${mineSection==='assigned'}">Minhas participações</button><button type="button" data-action="open_list" aria-pressed="${mineSection==='open'}">Vagas abertas (${openEvents().length})</button></div>`+`<div class="ccs-filters">${select('Período','period',`<option value="future" ${filter.period==='future'?'selected':''}>Próximas</option><option value="past" ${filter.period==='past'?'selected':''}>Histórico</option>`)}${input('Buscar celebração ou equipe','search','search',filter.q,false)}</div><div id="ccs-events" class="ccs-event-grid"></div>`;renderMine();
  }
  function renderMine(){eventViews.mineList();}
  function teams(){teamCatalog();content.insertAdjacentHTML('beforeend',eventViews.teamOpportunities());}
  function teamCatalog(){
    content.innerHTML=heading('SERVIMOS EM COMUNIDADE','Minhas equipes','Toque em uma equipe para consultar os detalhes.')+'<div class="ccs-event-grid">'+state.teams.filter(t=>t.visible_to_me!==false).map(t=>'<button type="button" class="ccs-card ccs-team-summary" data-action="team_details" data-id="'+num(t.id)+'" aria-haspopup="dialog"><span class="ccs-eyebrow">'+e(state.departments.find(d=>same(d.id,t.department_id))?.name)+'</span><strong class="ccs-team-summary-title">'+e(t.name)+'</strong><span>Responsável: '+e(t.leader_id?user(t.leader_id):'Não definido')+'</span><span>'+t.members.length+' '+(t.members.length===1?'integrante':'integrantes')+'</span></button>').join('')+'</div>';
    if(!state.teams.some(t=>t.visible_to_me!==false))content.insertAdjacentHTML('beforeend',empty('Você ainda não foi vinculado a uma equipe.'));
  }
  function teamDetails(id){
    const t=state.teams.find(t=>same(t.id,id));if(!t||t.visible_to_me===false){notify('Esta equipe não está disponível para consulta.',true);return;}
    openedOccurrence=0;
    const people=t.members.length?'<ul class="ccs-people">'+t.members.map(id=>'<li><span class="ccs-avatar" aria-hidden="true">'+e(user(id).slice(0,1))+'</span>'+e(user(id))+(state.users.find(u=>same(u.id,id))?.active?'':' (inativo)')+'</li>').join('')+'</ul>':'<p>Nenhum integrante vinculado.</p>';
    const functions=(t.functions||[]).map(f=>'<div class="ccs-list-row"><div><strong>'+e(f.name)+'</strong><p>'+num(f.quantity)+' vaga(s) por celebração</p><p>'+(f.members.filter(id=>t.members.some(m=>same(m,id))).map(user).map(e).join(', ')||'Sem integrantes habilitados')+'</p></div></div>').join('')||'<p>Nenhuma função selecionada para esta equipe.</p>';
    open(t.name,'<span class="ccs-eyebrow">'+e(state.departments.find(d=>same(d.id,t.department_id))?.name)+'</span><p>Responsável: '+e(t.leader_id?user(t.leader_id):'Não definido')+'</p><p>'+t.members.length+' '+(t.members.length===1?'integrante':'integrantes')+' · '+e(modeLabel(t.mode))+'</p><h3>Integrantes</h3>'+people+'<div class="ccs-function-list"><h3>Funções</h3>'+functions+'</div><div class="ccs-actions">'+(t.can_functions?button('Selecionar funções','team_functions',t.id):'')+(t.can_manage?button('Editar equipe','team',t.id):'')+'</div>');
  }
  function manage(){
    if(!manageable()){view='home';render();return;}
    if(manageSection==='dashboard'){eventViews.dashboard();return;}
    if(manageSection==='celebrations'&&plansAllowed()){celebrationsView();return;}
    content.innerHTML=managementTabs()+heading('CUIDADO COM CADA EQUIPE','Gestão de eventos','Publique os departamentos necessários e acompanhe a participação das equipes.')+`<div class="ccs-actions ccs-management-actions">${state.me.import_url?`<a class="ccs-button secondary" href="${e(state.me.import_url)}">Importar pessoas</a>`:''}${!state.me.secretary?button('＋ Publicar evento','publish_event','',''):''}${(state.can_catalog||state.me.secretary)?button('Cadastro geral de funções','catalog'):''}${plansAllowed()&&!state.me.secretary?button('Nova equipe','team'):''}${state.me.pastor?button('Novo departamento','department')+button('Cadastrar pessoa','user'):''}</div><section class="ccs-card"><h2>Departamentos</h2>${state.departments.filter(d=>state.me.secretary||d.can_manage).map(d=>`<div class="ccs-list-row"><div><strong>${e(d.name)}</strong><p>${e(d.leader_id?user(d.leader_id):'Sem líder definido')}</p></div>${state.me.pastor?button('Editar','department',d.id,'text'):''}</div>`).join('')||'<p>Cadastre o primeiro departamento para começar.</p>'}</section><h2>Eventos publicados</h2><div class="ccs-filters">${select('Equipe','team-filter','<option value="">Todas as equipes</option>'+state.teams.filter(t=>state.me.secretary||t.can_manage||t.can_publish_open).map(t=>`<option value="${num(t.id)}" ${same(t.id,filter.team)?'selected':''}>${e(t.name)}</option>`).join(''))}${select('Período','period',`<option value="future" ${filter.period==='future'?'selected':''}>Próximas</option><option value="past" ${filter.period==='past'?'selected':''}>Histórico</option>`)}</div><div id="ccs-managed" class="ccs-event-grid"></div>${manageable()?`<section class="ccs-card"><h2>Pessoas cadastradas</h2><p>${state.me.secretary?'Consulta de pessoas, contatos e funções.':'Atribua funções sem alterar o perfil de acesso da pessoa.'}</p><label class="ccs-field">Buscar por nome<input type="search" name="people-search" value="${e(peopleQuery)}" placeholder="Digite o nome da pessoa" autocomplete="off" aria-controls="ccs-people-results"></label><p id="ccs-people-summary" class="ccs-hint" role="status" aria-live="polite"></p><div id="ccs-people-results"></div><nav class="ccs-people-pagination" aria-label="Paginação de pessoas"><button class="ccs-button secondary" type="button" data-action="people_previous">Anterior</button><span id="ccs-people-page"></span><button class="ccs-button secondary" type="button" data-action="people_next">Próxima</button></nav></section>`:''}`;
    renderManaged();renderPeople();
  }
  function peoplePageData(users,query,page){
    const q=normalizeName(query),list=users.filter(u=>!u.deleted&&normalizeName(u.name).includes(q));
    const pages=Math.max(1,Math.ceil(list.length/peoplePageSize)),current=Math.max(1,Math.min(page,pages));
    return {total:list.length,pages,page:current,rows:list.slice((current-1)*peoplePageSize,current*peoplePageSize)};
  }
  function renderPeople(){
    const target=content.querySelector('#ccs-people-results');if(!target)return;
    const data=peoplePageData(state.users,peopleQuery,peoplePage);peoplePage=data.page;
    target.innerHTML=data.rows.map(u=>`<div class="ccs-list-row"><div><strong>${e(u.name)}</strong><p>${e(u.email||'')} · ${u.active?'Ativo':'Inativo'}</p><p>${e(u.phone||'')}</p><p>${(u.function_ids||[]).map(id=>state.functions.find(f=>same(f.id,id))?.name).filter(Boolean).map(e).join(', ')||'Sem funções'}</p></div><div class="ccs-actions">${state.me.can_assign_functions&&active(u)?button('Atribuir funções','person_functions',u.id,'text'):''}${state.me.pastor&&!same(u.id,state.me.id)&&!u.roles?.includes('administrator')?button('Editar','user',u.id,'text'):''}</div></div>`).join('')||'<p>Nenhuma pessoa encontrada.</p>';
    content.querySelector('#ccs-people-summary').textContent=data.total?`Mostrando ${(data.page-1)*peoplePageSize+1}–${Math.min(data.page*peoplePageSize,data.total)} de ${data.total} pessoa(s).`:'Nenhuma pessoa encontrada.';
    content.querySelector('#ccs-people-page').textContent=`Página ${data.page} de ${data.pages}`;
    content.querySelector('.ccs-people-pagination').hidden=data.pages<=1;
    content.querySelector('[data-action="people_previous"]').disabled=data.page<=1;
    content.querySelector('[data-action="people_next"]').disabled=data.page>=data.pages;
  }
  function renderManaged(){eventViews.managed();}
  function profile(){profileBase();eventViews.profilePush();}
  function profileBase(){
    const ownTeams=state.teams.filter(t=>t.members.some(id=>same(id,state.me.id))||same(t.leader_id,state.me.id));
    const functions=t=>(t.functions||[]).filter(f=>t.members.some(id=>same(id,state.me.id))&&f.members.some(id=>same(id,state.me.id)));
    const chosen=state.functions.filter(f=>(state.users.find(u=>same(u.id,state.me.id))?.function_ids||[]).some(id=>same(id,f.id)));
    const count=chosen.length,upcoming=eventViews.ownEvents().length;
    const initials=state.me.name.trim().split(/\s+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('');
    content.innerHTML=`<section class="ccs-profile-hero"><div class="ccs-profile-identity"><div class="ccs-profile-monogram" aria-hidden="true">${e(initials)}</div><div class="ccs-profile-name"><h1 tabindex="-1">${e(state.me.name)}</h1><span class="ccs-profile-role">${e(state.me.role_label)}</span></div></div><p>Seu tempo e seus dons fazem parte da nossa comunidade.</p><div class="ccs-profile-stats"><div><strong>${ownTeams.length}</strong><span>Equipes</span></div><div><strong>${count}</strong><span>Funções</span></div><div><strong>${upcoming}</strong><span>Próximas escalas</span></div></div></section><div class="ccs-profile-layout"><section class="ccs-profile-section"><div class="ccs-card"><h2>Minhas funções</h2><div class="ccs-function-chips">${chosen.map(f=>`<span class="ccs-function-chip">${e(f.name)}</span>`).join('')||'<p>Conte para nós como você pode servir.</p>'}</div>${state.me.can_serve!==false?button('Escolher minhas funções','profile_functions','',''):'<p>Acesso de consulta. Este perfil não participa de escalas.</p>'}</div><div class="ccs-account-heading"><h2>Onde eu sirvo</h2><span class="ccs-count-pill">${ownTeams.length}</span></div>${ownTeams.map(t=>`<article class="ccs-card"><div class="ccs-my-team-title"><span class="ccs-team-symbol" aria-hidden="true">${e(t.name.slice(0,1))}</span><div><span class="ccs-eyebrow">${e(state.departments.find(d=>same(d.id,t.department_id))?.name)}</span><h3>${e(t.name)}</h3></div></div><div class="ccs-function-chips">${same(t.leader_id,state.me.id)?'<span class="ccs-function-chip leader">Líder da equipe</span>':''}${functions(t).map(f=>`<span class="ccs-function-chip">${e(f.name)}</span>`).join('')}</div>${!functions(t).length?'<p class="ccs-hint">Sem função vinculada. Escolha suas funções no perfil. A equipe precisa ter a mesma função selecionada.</p>':''}<p class="ccs-hint" style="margin-top:14px">Liderança: ${e(t.leader_id?user(t.leader_id):'Não definida')}</p>${button('Ver minhas escalas','mine_assigned',t.id,'text')}</article>`).join('')||empty('Seu cadastro está pronto. Escolha suas funções acima. A liderança poderá vincular você às equipes.')}<div class="ccs-card"><h2>Meus dados</h2><div class="ccs-contact-line"><span>E-mail</span><strong>${e(state.me.email)}</strong></div><div class="ccs-contact-line"><span>Telefone</span><strong>${e(state.me.phone||'Não informado')}</strong></div><p class="ccs-hint" style="margin-top:14px">Para atualizar seus dados ou vínculos, procure a liderança.</p></div></section><section class="ccs-profile-section"><div class="ccs-card"><div class="ccs-security-heading"><span class="ccs-security-symbol" aria-hidden="true">◎</span><div><h2>Acesso com biometria</h2><p>${state.passkeys.length?'Ativado na sua conta':'Mais praticidade no próximo acesso'}</p></div></div><p class="ccs-hint">Use digital, Face ID ou PIN do dispositivo. Sua biometria fica com o aparelho ou provedor de acesso.</p>${state.passkeys.map(k=>`<div class="ccs-device-row"><div><strong>${e(k.label)}</strong><p>${k.last_used?'Último uso: '+e(stamp(k.last_used)):'Ativado: '+e(stamp(k.created_at))}</p></div>${button('Remover','passkey_remove',k.id,'text')}</div>`).join('')}${state.passkey_available&&window.CCS_PASSKEYS?.supported()?button('Ativar neste dispositivo','passkey_add','',''):'<p class="ccs-hint">Biometria indisponível neste navegador ou endereço. Sua senha continua funcionando.</p>'}<p class="ccs-hint" style="margin-top:14px">Um acesso pode ser sincronizado entre aparelhos pelo seu provedor. Removê-lo revoga essa chave em todos eles.</p></div><div class="ccs-card"><h2>Segurança da conta</h2><p class="ccs-hint">Você pode entrar com sua senha sempre que precisar.</p><a class="ccs-button secondary" href="${e(CCS_CONFIG.lost)}">Redefinir minha senha</a></div><div class="ccs-profile-footer"><a class="ccs-button secondary" href="${e(CCS_CONFIG.logout)}">Sair da conta</a><p>Horários da igreja: ${e(state.timezone)}</p></div></section></div>`;
  }
  function passkeyForm(){open('Ativar biometria',form('passkey_add','<p>Confirme sua senha uma vez. Em seguida, o aparelho pedirá sua digital, Face ID ou PIN.</p>'+input('Nome deste acesso','label','text',CCS_PASSKEYS.deviceName(),true,'maxlength="100"')+input('Sua senha atual','password','password','',true,'autocomplete="current-password"'),0,'Ativar biometria'));}
  async function passkeySave(data){if(busy)return;busy=true;dialog.querySelectorAll('button').forEach(b=>b.disabled=true);try{const result=data.action==='passkey_add'?await CCS_PASSKEYS.register(data.label,data.password):await CCS_PASSKEYS.revoke(num(data.id));close();notify(result.message);await load();}catch(err){const box=dialog.querySelector('.ccs-form-error');if(box){box.textContent=err.message;box.focus()}else notify(err.message,true)}finally{const field=dialog.querySelector('[name="password"]');if(field)field.value='';busy=false;dialog.querySelectorAll('button').forEach(b=>b.disabled=false)}}
  let biometricPrompted=false;
  async function biometricPrompt(){if(biometricPrompted||state.passkeys.length||!state.passkey_available||!window.CCS_PASSKEYS)return;biometricPrompted=true;try{if(sessionStorage.getItem('ccs-biometric-later'))return}catch{}if(!await CCS_PASSKEYS.platform()||view!=='home'||dialog.open||busy)return;open('Seu próximo acesso pode ser mais rápido',`<div class="ccs-biometric-intro"><span class="ccs-security-symbol" aria-hidden="true">◎</span><p>Ative a biometria para entrar com digital, Face ID ou PIN. Você continuará podendo usar sua senha.</p><div class="ccs-actions">${button('Ativar biometria','passkey_add','','')}${button('Agora não','passkey_later')}</div></div>`);}
  function eventDetails(id){const ev=state.events.find(ev=>same(ev.id,id));if(num(ev?.occurrence_id))eventViews.details(ev.occurrence_id);else legacyEventDetails(id);}
  function legacyEventDetails(id){
    const ev=state.events.find(ev=>same(ev.id,id));if(!ev)return;
    const slots=members(ev),canRespond=!state.me.secretary&&ev.status==='published'&&ev.starts>state.now;
    const counts={confirmed:0,pending:0,declined:0,available:0};slots.forEach(s=>counts[s.status]++);
    const cards=slots.map(s=>{
      const own=same(s.assigned_id,state.me.id),pending=state.invites.find(i=>same(i.slot_id,s.id)&&i.status==='pending');
      let actions='';
      if(canRespond&&s.status==='available'&&s.can_claim)actions=button('Assumir e confirmar esta vaga','claim',s.id,'');
      if(canRespond&&s.status==='available'&&ev.can_delegate)actions+=button('Delegar função','delegate',s.id);
      if(own&&canRespond){actions=(s.status!=='confirmed'?button('Confirmar participação','confirm',s.id,''):'')+(s.status!=='declined'?button('Não posso participar','decline',s.id):button(pending?'Escolher outro substituto':'Solicitar troca','invite',s.id))+(['open','functions'].includes(ev.mode)?button('Liberar vaga para a equipe','release_slot',s.id,'text'):'');}
      return `<article class="ccs-slot">${s.function_name?`<h4>${e(s.function_name)}</h4>`:''}<div class="ccs-slot-head"><strong>${s.status==='available'?'Vaga disponível':e(user(s.assigned_id))}${own?' · você':''}</strong>${badge(s.status)}</div>${!same(s.original_id,s.assigned_id)?`<p>Substituindo ${e(user(s.original_id))}</p>`:''}${pending?`<p>Convite aguardando ${e(user(pending.to_id))}</p>`:''}${actions?`<div class="ccs-actions">${actions}</div>`:''}</article>`;
    }).join('');
    open(ev.title,`<p>${e(ev.team_name)} · ${e(modeLabel(ev.mode))}</p><p>${e(ev.location)}</p><div class="ccs-info"><strong>${e(stamp(ev.starts))}</strong><span>Chegada: ${e(stamp(ev.arrival))}</span><span>Término: ${e(stamp(ev.ends))}</span></div>${ev.notes?`<p class="ccs-notes">${e(ev.notes)}</p>`:''}<div class="ccs-badges">${badge('confirmed',`${counts.confirmed} confirmados`)}${badge('pending',`${counts.pending} pendentes`)}${badge('declined',`${counts.declined+counts.available} sem cobertura`)}${ev.status==='cancelled'?badge('cancelled'):''}</div><h3>${ev.mode==='functions'?'Necessidades por função':ev.mode==='open'?'Quem vai servir nesta data?':'Convocações da equipe'}</h3>${cards}${ev.can_delegate&&canRespond?button('Ajustar necessidades por função','vacancies',ev.id):''}${(state.audit||[]).some(a=>same(a.event_id,ev.id))?`<details class="ccs-history"><summary>Histórico de alterações</summary>${state.audit.filter(a=>same(a.event_id,ev.id)).map(a=>`<p><strong>${e(a.actor_name)}</strong> · ${e(({function_delegated:'Delegou uma função',function_vacancies_changed:'Ajustou as vagas por função',slot_claimed:'Escolheu a vaga',slot_released:'Liberou a vaga',volunteer_deactivated:'Desativou um voluntário da escala',schedule_published:'Publicou a escala',schedule_cancelled:'Cancelou a escala',schedule_edited:'Editou a escala',response_confirmed:'Confirmou participação',response_declined:'Informou indisponibilidade',replacement_invited:'Convidou substituto',replacement_accepted:'Aceitou substituição',replacement_declined:'Recusou substituição'})[a.action]||a.action)}<br>${e(stamp(a.created_at))}</p>`).join('')}</details>`:''}${ev.can_manage&&canRespond?`<hr>${num(ev.occurrence_id)?'<p class="ccs-hint">Esta escala acompanha a data e os horários da celebração. Cancelá-la deixa o departamento sem esta equipe nessa ocorrência.</p>':''}<div class="ccs-actions">${button('Editar escala','edit_schedule',ev.id)}${button('Cancelar escala desta equipe','cancel',ev.id,'danger')}</div>`:''}${ev.can_manage?`<div class="ccs-delete-zone">${button('Excluir escala','delete_item','schedule:'+ev.id,'danger')}</div>`:''}`);
  }
  function catalog(){open('Cadastro geral de funções',`<p>Funções compartilhadas por todas as equipes. Os voluntários escolhem as suas no perfil.</p>${state.can_catalog?button('Nova função','function',0,''):''}<div class="ccs-function-list">${state.functions.map(f=>`<div class="ccs-list-row"><strong>${e(f.name)}</strong>${state.can_catalog?button('Editar','function',f.id,'text'):''}</div>`).join('')||'<p>Nenhuma função cadastrada.</p>'}</div>`);}
  function functionForm(id){const f=state.functions.find(f=>same(f.id,id));open(f?'Editar função geral':'Nova função geral',form('function',input('Nome da função','name','text',f?.name||'',true,'maxlength="150"')+'<p>Exemplo: Bateria, Guitarra, Teclado ou Técnico de transmissão. A função poderá ser usada em várias equipes.</p>',id));}
  function functionChoices(t){return '<fieldset><legend>Funções desta equipe</legend><p>Selecione as funções e a quantidade de vagas por celebração.</p>'+state.functions.map(f=>{const linked=t?.functions.find(x=>same(x.id,f.id));return `<div class="ccs-function-choice" data-function-row="${num(f.id)}"><label class="ccs-check"><input type="checkbox" name="team_function" value="${num(f.id)}" ${linked?'checked':''}>${e(f.name)}</label><label class="ccs-field">Vagas<input type="number" data-function-quantity min="1" max="30" value="${num(linked?.quantity||1)}" aria-label="Vagas de ${e(f.name)}"></label></div>`;}).join('')+(state.functions.length?'':'<p>A liderança precisa cadastrar as funções gerais primeiro.</p>')+'</fieldset>';}
  function collectFunctions(f){return [...f.querySelectorAll('[name="team_function"]:checked')].map(el=>({id:num(el.value),quantity:num(el.closest('[data-function-row]').querySelector('[data-function-quantity]').value)}));}
  function teamFunctionsForm(id){const t=state.teams.find(t=>same(t.id,id));open('Funções · '+t.name,form('team_functions',functionChoices(t)+'<p>As alterações valem para novas escalas. As vagas já publicadas permanecem.</p>',id));}
  function profileFunctions(){const mine=state.users.find(u=>same(u.id,state.me.id))?.function_ids||[];open('Minhas funções',form('profile_functions','<p>Marque as funções em que você pode servir. A liderança vincula você a uma ou mais equipes.</p><div class="ccs-checklist">'+state.functions.map(f=>`<label><input type="checkbox" name="function_ids" value="${num(f.id)}" ${mine.some(id=>same(id,f.id))?'checked':''}>${e(f.name)}</label>`).join('')+'</div><p class="ccs-hint">Alterar suas funções não cancela escalas que você já assumiu.</p>'));}
  function personFunctions(id){const u=state.users.find(u=>same(u.id,id));open('Funções · '+u.name,form('person_functions','<p>Marque as funções em que esta pessoa pode servir, em qualquer equipe à qual esteja vinculada.</p><div class="ccs-checklist">'+state.functions.map(f=>`<label><input type="checkbox" name="function_ids" value="${num(f.id)}" ${(u.function_ids||[]).some(fid=>same(fid,f.id))?'checked':''}>${e(f.name)}</label>`).join('')+'</div><p>As escalas já assumidas são preservadas.</p>',id));}
  function updateBell(){eventViews.updateBell();}
  async function notificationModal(){await eventViews.notificationModal();}
  function delegateForm(id){const s=state.slots.find(s=>same(s.id,id)),ev=state.events.find(ev=>same(ev.id,s.event_id)),t=state.teams.find(t=>same(t.id,ev.team_id)),f=t.functions.find(f=>same(f.id,s.function_id));open('Delegar · '+s.function_name,form('delegate',select('Integrante habilitado','to_id',options(state.users.filter(u=>active(u)&&t.members.some(m=>same(m,u.id))&&(u.function_ids||[]).some(fid=>same(fid,s.function_id)))))+'<p>A atribuição já fica confirmada. O voluntário poderá declinar e pedir uma troca.</p>',id,'Delegar função'));}
  function vacanciesForm(id){const ev=state.events.find(ev=>same(ev.id,id)),t=state.teams.find(t=>same(t.id,ev.team_id));open('Necessidades desta celebração',form('vacancies',select('Função','function_id',[...t.functions,...members(ev).filter(s=>num(s.function_id)&&!t.functions.some(f=>same(f.id,s.function_id))).filter((s,i,a)=>a.findIndex(x=>same(x.function_id,s.function_id))===i).map(s=>({id:s.function_id,name:s.function_name}))].map(f=>`<option value="${num(f.id)}">${e(f.name)} (${members(ev).filter(s=>same(s.function_id,f.id)).length} vagas nesta data)</option>`).join(''))+input('Total desejado nesta data','quantity','number',1,true,'min="0" max="30"')+'<p>Informe a quantidade total, incluindo vagas ocupadas. Somente vagas livres podem ser removidas. Zero remove todas as vagas livres desta função.</p>',id,'Atualizar necessidades'));}
  function departmentForm(id){const d=state.departments.find(d=>same(d.id,id));open(d?'Editar departamento':'Novo departamento',form('department',input('Nome do departamento','name','text',d?.name||'',true,'maxlength="150"')+select('Líder de departamento','leader_id',options(state.users.filter(active),d?.leader_id,'Sem líder')),id));}
  function teamMemberField(){
    return '<fieldset id="ccs-team-members"><legend>Integrantes da equipe</legend><p>Busque pelo nome e selecione quem fará parte da equipe. Inclua o líder se ele também servir.</p><section class="ccs-member-selection" aria-label="Integrantes selecionados"><h3 data-member-heading>Selecionados</h3><div data-member-selected class="ccs-member-chips"></div></section><label class="ccs-field" for="ccs-team-member-search">Buscar integrante pelo nome<input id="ccs-team-member-search" type="search" placeholder="Digite o nome da pessoa" autocomplete="off" spellcheck="false" data-member-search aria-controls="ccs-team-member-results"></label><p class="ccs-hint" data-member-summary role="status" aria-live="polite"></p><div id="ccs-team-member-results" class="ccs-checklist ccs-member-results" data-member-results></div></fieldset>';
  }
  function renderTeamMembers(){
    const field=dialog.querySelector('#ccs-team-members');if(!field||!teamMemberDraft)return;
    const users=state.users.filter(active),query=normalizeName(field.querySelector('[data-member-search]').value);
    const selected=[...teamMemberDraft].map(id=>users.find(u=>same(u.id,id))).filter(Boolean);
    field.querySelector('[data-member-heading]').textContent='Selecionados ('+selected.length+')';
    field.querySelector('[data-member-selected]').innerHTML=selected.map(u=>'<div class="ccs-member-chip"><span>'+e(u.name)+'</span><button type="button" data-action="team_member_remove" data-id="'+num(u.id)+'" aria-label="Remover '+e(u.name)+' da seleção">×</button><input type="hidden" name="members" value="'+num(u.id)+'"></div>').join('')||'<p class="ccs-hint">Nenhum integrante selecionado.</p>';
    const matches=users.filter(u=>!teamMemberDraft.has(num(u.id))&&normalizeName(u.name).includes(query));
    field.querySelector('[data-member-summary]').textContent=matches.length+' pessoa(s) encontrada(s) · '+selected.length+' selecionada(s)';
    field.querySelector('[data-member-results]').innerHTML=matches.map(u=>'<label class="ccs-member-option"><input type="checkbox" data-member-add value="'+num(u.id)+'"><span class="ccs-member-option-copy"><strong>'+e(u.name)+'</strong><span>'+((u.function_ids||[]).map(id=>state.functions.find(f=>same(f.id,id))?.name).filter(Boolean).map(e).join(', ')||'Sem função')+'</span></span></label>').join('')||'<p class="ccs-member-empty">'+(query?'Nenhuma outra pessoa encontrada para este nome.':'Nenhuma outra pessoa disponível para adicionar.')+'</p>';
  }
  function teamForm(id){const t=state.teams.find(t=>same(t.id,id)),deps=state.departments.filter(d=>state.me.secretary||d.can_manage);if(!deps.length){notify('Cadastre primeiro um departamento.',true);return;}
    open(t?'Editar equipe':'Nova equipe',form('team',input('Nome da equipe','name','text',t?.name||'',true,'maxlength="150"')+select('Departamento','department_id',deps.filter(d=>!t||same(d.id,t.department_id)).map(d=>`<option value="${num(d.id)}" ${same(d.id,t?.department_id)?'selected':''}>${e(d.name)}</option>`).join(''))+select('Líder de equipe','leader_id',options(state.users.filter(active),t?.leader_id,'Sem líder'))+select('Modo padrão das novas escalas','mode',`<option value="functions" ${!t||t.mode==='functions'?'selected':''}>Vagas por função — integrantes se voluntariam</option><option value="roster" ${t?.mode==='roster'?'selected':''}>Convocar equipe inteira</option><option value="open" ${t?.mode==='open'?'selected':''}>Vaga aberta — 1 pessoa escolhe a data</option>`)+teamMemberField()+functionChoices(t)+'<p class="ccs-hint">Alterações nos integrantes valem para novas escalas. As já publicadas preservam suas convocações.</p>',id));
    teamMemberDraft=new Set((t?.members||[]).map(num).filter(id=>state.users.some(u=>same(u.id,id)&&active(u))));renderTeamMembers();
  }
  function userForm(id){const u=state.users.find(u=>same(u.id,id)),roles={ccs_pastor:'Pastor',ccs_department:'Líder de departamento',ccs_team:'Líder de equipe',ccs_volunteer:'Voluntário',ccs_secretary:'Secretaria (consulta)'};open(u?'Editar pessoa':'Cadastrar pessoa',form('user',input('Nome completo','name','text',u?.name||'',true,'maxlength="150"')+input('E-mail','email','email',u?.email||'')+input('Telefone com DDD','phone','tel',u?.phone||'',false,'maxlength="25"')+select('Perfil','role',Object.entries(roles).map(([v,l])=>`<option value="${v}" ${(u?u.roles?.includes(v):v==='ccs_volunteer')?'selected':''}>${l}</option>`).join(''))+(u?`<label class="ccs-check"><input name="active" type="checkbox" ${u.active?'checked':''}>Cadastro ativo</label>`:'<p>O primeiro acesso é feito por “Perdeu a senha?” usando este e-mail. Configure a entrega de e-mails do WordPress.</p>'),id));}
  function scheduleForm(){eventViews.publishForm();}
  function editScheduleForm(id){eventViews.teamEditForm(id);}
  function editOccurrenceForm(id){eventViews.editForm(id);}
  function deleteForm(type,id){
    const names={schedule:'escala',team:'equipe',department:'departamento',function:'função',user:'voluntário',celebration:'cadastro de celebração',occurrence:'data de celebração'};
    const messages={schedule:'A escala sai da agenda e seus convites pendentes são cancelados. Se pertencer a uma celebração, o departamento poderá ficar com uma pendência.',occurrence:'Esta data e todas as suas escalas sairão da agenda. Convites pendentes serão cancelados. Outras datas e o rodízio permanecem.',celebration:'O modelo sai dos cadastros. As datas e escalas já publicadas permanecem na agenda e podem ser excluídas separadamente.',team:'A equipe sai dos cadastros ativos. Suas funções gerais continuam disponíveis para outras equipes. Primeiro cancele/exclua suas escalas em andamento ou futuras e retire a equipe das regras de celebrações.',department:'O departamento sai dos cadastros ativos. Primeiro exclua suas equipes e retire o departamento das regras de celebrações.',function:'A função geral deixa de aparecer nos perfis e nas opções para novas escalas. Primeiro retire a função das equipes e suas vagas das escalas em andamento/futuras ou cancele/exclua essas escalas.',user:'O voluntário perde o acesso às escalas e seus vínculos com equipes/funções são removidos. Vagas abertas/por função futuras serão liberadas. Convites serão cancelados e passkeys removidas. A conta WordPress e o histórico ficam preservados. Se for líder, substitua-o na liderança primeiro.'};
    open('Excluir '+names[type]+'?',form('delete',`<input type="hidden" name="type" value="${e(type)}"><p>${e(messages[type])}</p><p class="ccs-hint">O registro é retirado do uso ativo, com histórico preservado. Não há restauração pelo painel nesta versão.</p><label class="ccs-check"><input type="checkbox" name="confirm" required>Confirmo a exclusão deste item</label>`,id,'Excluir '+names[type]));
  }
  function inviteForm(id){const s=state.slots.find(s=>same(s.id,id)),candidates=state.users.filter(u=>active(u)&&!same(u.id,state.me.id)&&(!num(s.function_id)||(u.function_ids||[]).some(fid=>same(fid,s.function_id))));open('Trocar · '+(s.function_name||'Minha escala'),form('invite',`<p>Escolha um voluntário ${num(s.function_id)?'da mesma função':'ativo'}, inclusive de outra equipe. A troca só será concluída quando ele aceitar.</p>`+select('Quem pode substituir você?','to_id',options(candidates))+(candidates.length?'':'<p>Nenhum outro voluntário tem esta função no perfil.</p>')+'<p class="ccs-hint">O convite aparecerá no sino do aplicativo da pessoa escolhida. Enviar outro convite cancela o anterior.</p>',s.id,'Enviar pedido de troca'));}
  function managementTabs(){return plansAllowed()?'<div class="ccs-tabs">'+[['dashboard','Painel de eventos'],['schedules','Equipes e cadastros'],['celebrations','Celebrações']].map(([section,label])=>'<button type="button" data-action="manage_'+section+'" aria-pressed="'+(manageSection===section)+'">'+e(label)+'</button>').join('')+'</div>':'';}
  function celebrationsView(){
    const list=(state.occurrences||[]).filter(o=>filter.period==='future'?o.ends>=state.now:o.ends<state.now).sort((a,b)=>filter.period==='future'?a.starts.localeCompare(b.starts):b.starts.localeCompare(a.starts));
    content.innerHTML=managementTabs()+heading('UMA CELEBRAÇÃO, VÁRIAS EQUIPES','Celebrações','Defina os departamentos uma vez e organize as equipes de cada data.')+(state.me.pastor?`<div class="ccs-actions ccs-management-actions">${button('＋ Cadastrar celebração','celebration','','')}</div>`:'')+`<div class="ccs-event-grid">${(state.celebrations||[]).map(c=>`<article class="ccs-card"><span class="ccs-eyebrow">CADASTRO DA CELEBRAÇÃO</span><h2>${e(c.name)}</h2><p>${e(c.starts_time)}–${e(c.ends_time)} · ${e(c.location)}</p><p>${c.rules.length} departamentos previstos${state.me.pastor?'':' sob sua liderança'}</p><div class="ccs-actions">${state.me.pastor?button('Gerar datas','generate_dates',c.id,'')+button('Editar cadastro','celebration',c.id):''}</div></article>`).join('')||empty('O pastor pode cadastrar a primeira celebração e definir os departamentos envolvidos.')}</div><div class="ccs-title-row"><h2>Agenda de celebrações</h2>${button('Atualizar','refresh','','text')}</div>${select('Período','occurrence-period',`<option value="future" ${filter.period==='future'?'selected':''}>Próximas datas</option><option value="past" ${filter.period==='past'?'selected':''}>Histórico</option>`)}<div class="ccs-event-grid">${list.map(eventViews.card).join('')||empty('Nenhuma data gerada neste período.')}</div>`;
  }
  function orderedTeams(dep,selected){const list=state.teams.filter(t=>same(t.department_id,dep));return [...selected.map(id=>list.find(t=>same(t.id,id))).filter(Boolean),...list.filter(t=>!selected.some(id=>same(id,t.id)))];}
  function ruleCard(d,r){
    const enabled=!!r,policy=r?.policy||'claim',selected=r?.team_ids||[];
    return `<fieldset class="ccs-rule" data-rule="${num(d.id)}"><legend><label><input type="checkbox" data-rule-enabled ${enabled?'checked':''}> ${e(d.name)}</label></legend><div data-rule-controls ${enabled?'':'hidden'}><label class="ccs-check"><input type="checkbox" data-rule-required ${!r||r.required?'checked':''}> Obrigatório nesta celebração</label><label class="ccs-field">Como definir as equipes?<select data-rule-policy><option value="claim" ${policy==='claim'?'selected':''}>O líder da equipe assume a data</option><option value="manual" ${policy==='manual'?'selected':''}>Escolher em cada data</option><option value="fixed" ${policy==='fixed'?'selected':''}>Sempre as mesmas equipes</option><option value="rotation" ${policy==='rotation'?'selected':''}>Rodízio: uma equipe por data</option></select></label><label class="ccs-field">Quantidade de equipes necessárias<input type="number" data-rule-count min="1" max="30" value="${num(r?.team_count||1)}"></label><div data-rule-team-list ${['manual','claim'].includes(policy)?'hidden':''}><p class="ccs-hint">Marque as equipes. No rodízio, use as setas para definir a sequência de cima para baixo.</p>${orderedTeams(d.id,selected).map(t=>`<div class="ccs-order-row" data-order-team="${num(t.id)}"><label><input type="checkbox" value="${num(t.id)}" ${selected.some(id=>same(id,t.id))?'checked':''}>${e(t.name)}</label><div><button type="button" data-action="rule_up" aria-label="Mover ${e(t.name)} para cima">↑</button><button type="button" data-action="rule_down" aria-label="Mover ${e(t.name)} para baixo">↓</button></div></div>`).join('')||'<p>Cadastre equipes neste departamento para usar esta regra.</p>'}</div></div></fieldset>`;
  }
  function updateRuleControls(card){if(!card)return;card.querySelector('[data-rule-controls]').hidden=!card.querySelector('[data-rule-enabled]').checked;card.querySelector('[data-rule-team-list]').hidden=card.querySelector('[data-rule-policy]').value==='manual'||card.querySelector('[data-rule-policy]').value==='claim';}
  function collectRules(form){return [...form.querySelectorAll('[data-rule]')].filter(card=>card.querySelector('[data-rule-enabled]').checked).map(card=>({department_id:num(card.dataset.rule),required:card.querySelector('[data-rule-required]').checked,policy:card.querySelector('[data-rule-policy]').value,team_count:num(card.querySelector('[data-rule-count]').value),team_ids:[...card.querySelectorAll('[data-order-team] input:checked')].map(i=>num(i.value))}));}
  function celebrationForm(id){
    const c=(state.celebrations||[]).find(c=>same(c.id,id));
    if(!state.departments.length){notify('Cadastre os departamentos antes da celebração.',true);return;}
    open(c?'Editar celebração':'Cadastrar celebração',form('celebration',`<input type="hidden" name="revision" value="${num(c?.revision||0)}">`+input('Nome da celebração','name','text',c?.name||'',true,'maxlength="150"')+input('Local padrão','location','text',c?.location||'',false,'maxlength="200"')+input('Horário de início','starts_time','time',c?.starts_time||'19:00')+input('Horário de término','ends_time','time',c?.ends_time||'21:00')+input('Chegada: minutos antes do início','arrival_minutes','number',c?.arrival_minutes??30,true,'min="0" max="480"')+'<h3>Departamentos envolvidos</h3><p>O departamento pode ser obrigatório sem ter uma equipe fixa. Deixe o líder assumir a data, use o rodízio ou escolha equipes fixas.</p>'+state.departments.map(d=>ruleCard(d,c?.rules.find(r=>same(r.department_id,d.id)))).join('')+'<p class="ccs-hint">Alterar este cadastro não muda datas já geradas. Mudar a ordem das equipes reinicia o rodízio na primeira equipe selecionada.</p>',id));
  }
  function generateForm(id){const c=state.celebrations.find(c=>same(c.id,id));previewDraft=null;open('Gerar datas · '+c.name,form('celebration_preview',input('Primeira data','date','date')+input('Quantidade de datas','repeat','number',1,true,'min="1" max="12"')+select('Intervalo','interval','<option value="7">Semanal</option><option value="14">Quinzenal</option><option value="28">A cada quatro semanas</option>')+'<label class="ccs-field">Orientações para estas datas<textarea name="notes" rows="3" maxlength="3000"></textarea></label><p>A próxima tela mostra as equipes de cada data. Você poderá ajustar as escolhas antes de publicar.</p>',id,'Conferir equipes e datas'));}
  async function previewDates(data){
    if(busy)return;busy=true;dialog.querySelectorAll('button').forEach(b=>b.disabled=true);
    try{
      const result=await api('action',data);previewDraft={...data,revision:result.revision};
      open('Conferir antes de publicar',form('create_occurrences','<p>Equipes fixas e rodízio já aparecem selecionados. Você pode ajustar qualquer data. Departamentos sem equipe aguardam a liderança assumir a data.</p>'+result.preview.map(entry=>`<section class="ccs-preview-date"><h3>${e(stamp(entry.data.starts))}</h3>${entry.rules.map(r=>`<fieldset data-selection-index="${entry.index}" data-department-id="${num(r.department_id)}"><legend>${e(r.department_name)} ${r.required?'· obrigatório':'· opcional'}</legend><div class="ccs-checklist">${state.teams.filter(t=>same(t.department_id,r.department_id)).map(t=>`<label><input type="checkbox" value="${num(t.id)}" ${r.selected_team_ids.some(id=>same(id,t.id))?'checked':''}>${e(t.name)} · ${e(modeLabel(t.mode))}</label>`).join('')||'<p>Departamento sem equipes cadastradas.</p>'}</div></fieldset>`).join('')}</section>`).join(''),data.id,'Publicar datas e escalas'));
    }catch(err){notify(err.message,true);const error=dialog.querySelector('.ccs-form-error');if(error)error.textContent=err.message;}
    finally{busy=false;dialog.querySelectorAll('button').forEach(b=>b.disabled=false);}
  }
  function occurrenceDetails(id){eventViews.details(id);}
  function assignmentForm(id,department){const o=state.occurrences.find(o=>same(o.id,id)),r=o.requirements.find(r=>same(r.department_id,department));open('Equipes · '+r.department_name,form('assign_occurrence',`<input type="hidden" name="department_id" value="${num(department)}"><input type="hidden" name="fingerprint" value="${e(r.fingerprint)}"><p>${e(o.title)} · ${e(stamp(o.starts))}</p><div class="ccs-checklist">${state.teams.filter(t=>same(t.department_id,department)).map(t=>`<label><input type="checkbox" name="team_ids" value="${num(t.id)}" ${r.events.some(ev=>same(ev.team_id,t.id))?'checked':''}>${e(t.name)} · ${e(modeLabel(t.mode))}</label>`).join('')}</div><p class="ccs-hint">As equipes que permanecerem selecionadas mantêm suas confirmações e convites. Somente as equipes retiradas terão a participação cancelada. Respeite a quantidade de equipes solicitada para este departamento.</p>`,id,'Salvar equipes desta data'));}
  root.addEventListener('click',async event=>{
    const tab=event.target.closest('[data-view]');if(tab){view=tab.dataset.view;filter.q='';render();content.querySelector('h1')?.focus();window.scrollTo({top:0});return;}
    const el=event.target.closest('[data-action]');if(!el||busy)return;const id=num(el.dataset.id);
    switch(el.dataset.action){
      case 'team_details':teamDetails(id);break;
      case 'manage_dashboard':view='manage';manageSection='dashboard';render();break;
      case 'dashboard_reset':Object.assign(dashboardFilter,{period:'future',month:'',department:'',status:'published'});eventViews.dashboard();break;
      case 'team_member_remove':if(teamMemberDraft){teamMemberDraft.delete(id);renderTeamMembers();dialog.querySelector('[data-member-search]')?.focus();}break;
      case 'delete_item':{const [type,target]=el.dataset.id.split(':');deleteForm(type,num(target));break;}
      case 'publish_event':eventViews.publishForm();break;
      case 'claim_event_team':eventViews.claimForm(el.dataset.id,false);break;
      case 'claim_event_department':eventViews.claimForm(el.dataset.id,true);break;
      case 'release_event_team':eventViews.releaseForm(id);break;
      case 'notice_open':await eventViews.openNotice(id);break;
      case 'notices_read':await eventViews.readNotices();break;
      case 'edit_occurrence':editOccurrenceForm(id);break;
      case 'function':functionForm(id);break;
      case 'catalog':catalog();break;
      case 'team_functions':teamFunctionsForm(id);break;
      case 'profile_functions':profileFunctions();break;
      case 'person_functions':personFunctions(id);break;
      case 'people_previous':peoplePage--;renderPeople();break;
      case 'people_next':peoplePage++;renderPeople();break;
      case 'notifications':await notificationModal();break;
      case 'delegate':delegateForm(id);break;
      case 'vacancies':vacanciesForm(id);break;
      case 'passkey_add':passkeyForm();break;
      case 'passkey_later':try{sessionStorage.setItem('ccs-biometric-later','1')}catch{}close();break;
      case 'passkey_remove':open('Remover este acesso?',form('passkey_remove','<p>Esta chave deixará de permitir a entrada na sua conta, inclusive nos aparelhos onde estiver sincronizada. Você poderá continuar entrando com senha.</p>',id,'Remover acesso'));break;
      case 'mine_assigned':mineSection='assigned';view='mine';render();break;
      case 'open_list':mineSection='open';filter.period='future';view='mine';render();break;
      case 'manage_schedules':view='manage';manageSection='schedules';render();break;
      case 'manage_celebrations':manageSection='celebrations';render();break;
      case 'celebration':celebrationForm(id);break;
      case 'generate_dates':generateForm(id);break;
      case 'occurrence':occurrenceDetails(id);break;
      case 'assign_occurrence':{const [occ,dep]=el.dataset.id.split(':').map(num);assignmentForm(occ,dep);break;}
      case 'cancel_occurrence':open('Cancelar esta celebração?',form('cancel_occurrence','<p>Todas as escalas e convites desta ocorrência serão cancelados. O histórico e a ordem do rodízio serão preservados.</p>',id,'Cancelar celebração'));break;
      case 'claim':await save({action:'claim',id});break;
      case 'release_slot':open('Liberar esta vaga?',form('release_slot','<p>Outro integrante poderá escolher esta data. Qualquer convite de substituição pendente será cancelado.</p>',id,'Liberar vaga'));break;
      case 'rule_up':case 'rule_down':{const row=el.closest('[data-order-team]');if(el.dataset.action==='rule_up'&&row.previousElementSibling)row.before(row.previousElementSibling);if(el.dataset.action==='rule_down'&&row.nextElementSibling)row.after(row.nextElementSibling);break;}
      case 'refresh':try{await load();notify('Escalas atualizadas.');}catch(err){notify(err.message,true);}break;
      case 'close':close();break;case 'event':eventDetails(id);break;case 'department':departmentForm(id);break;case 'team':teamForm(id);break;case 'user':userForm(id);break;case 'schedule':scheduleForm();break;case 'edit_schedule':editScheduleForm(id);break;case 'invite':inviteForm(id);break;
      case 'confirm':await save({action:'respond',id,status:'confirmed'});break;
      case 'decline':await save({action:'respond',id,status:'declined'});if(state.slots.some(s=>same(s.id,id)&&s.status==='declined'&&num(s.function_id)))inviteForm(id);break;
      case 'accept':await save({action:'answer_invite',id,accept:true});break;
      case 'reject':await save({action:'answer_invite',id,accept:false});break;
      case 'cancel':open('Cancelar esta escala?',form('cancel','<p>As convocações e os convites pendentes desta equipe serão cancelados. O histórico será preservado.</p>',id,'Confirmar cancelamento'));break;
    }
  });
  root.addEventListener('submit',event=>{const f=event.target.closest('[data-form]');if(!f)return;event.preventDefault();const fd=new FormData(f),data=Object.fromEntries(fd);data.action=f.dataset.form;['members','team_ids'].forEach(k=>{if(f.querySelector(`[name="${k}"]`))data[k]=fd.getAll(k).map(num);});if(data.action==='user')data.active=fd.has('active');if(data.action==='delete')data.confirm=fd.has('confirm');
    if(data.action==='passkey_add'||data.action==='passkey_remove'){passkeySave(data);return;}
    if(['profile_functions','person_functions'].includes(data.action))data.function_ids=fd.getAll('function_ids').map(num);
    if(data.action==='team')data.members=fd.getAll('members').map(num);
    if(data.action==='team'||data.action==='team_functions')data.functions=collectFunctions(f);
    if(data.action==='celebration')data.rules=collectRules(f);
    if(['publish_event','edit_occurrence'].includes(data.action))data.requirements=eventViews.collectRequirements(f);
    if(data.action==='celebration_preview'){previewDates(data);return;}
    if(data.action==='create_occurrences'){
      Object.assign(data,previewDraft);data.action='create_occurrences';
      data.selections=[...f.querySelectorAll('[data-selection-index]')].map(group=>({index:num(group.dataset.selectionIndex),department_id:num(group.dataset.departmentId),team_ids:[...group.querySelectorAll('input[type="checkbox"]:checked')].map(i=>num(i.value))}));
    }
    save(data);});
  root.addEventListener('input',event=>{if(event.target.matches('[data-member-search]'))renderTeamMembers();if(event.target.name==='people-search'){peopleQuery=event.target.value;peoplePage=1;renderPeople();}if(event.target.name==='search'){filter.q=event.target.value;renderMine();}});
  root.addEventListener('change',event=>{if((event.target.name||'').startsWith('dashboard-')){const key=event.target.name.slice(10);if(Object.prototype.hasOwnProperty.call(dashboardFilter,key)){dashboardFilter[key]=event.target.value;if(key==='month'&&event.target.value)dashboardFilter.period='all';eventViews.dashboard();content.querySelector('[name="'+event.target.name+'"]')?.focus();}return;}if(event.target.matches('[data-member-add]')&&event.target.checked&&!busy&&teamMemberDraft){const id=num(event.target.value);if(state.users.some(u=>same(u.id,id)&&active(u))){teamMemberDraft.add(id);renderTeamMembers();dialog.querySelector('[data-member-search]')?.focus();}}if(event.target.matches('[data-rule-enabled],[data-rule-policy]'))updateRuleControls(event.target.closest('[data-rule]'));if(event.target.name==='occurrence-period'){filter.period=event.target.value;celebrationsView();}if(event.target.name==='period'){filter.period=event.target.value;view==='mine'?renderMine():renderManaged();}if(event.target.name==='team-filter'){filter.team=event.target.value;renderManaged();}});
  dialog.addEventListener('keydown',event=>{if(event.target.matches('[data-member-search]')&&event.key==='Enter')event.preventDefault();});
  dialog.addEventListener('cancel',event=>{if(busy)event.preventDefault();else openedOccurrence=0;});
  window.addEventListener('offline',()=>notify('Sem conexão. Suas ações precisam de internet para serem salvas.',true));
  window.addEventListener('online',()=>{notify('Conexão restabelecida.');if(!dialog.open&&!busy)load().catch(err=>notify(err.message,true));});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!dialog.open&&!busy)load().catch(err=>notify(err.message,true));});
  let notificationPolling=false;
  setInterval(async()=>{if(!state||busy||document.hidden||!navigator.onLine||notificationPolling)return;notificationPolling=true;try{eventViews.setFeed(await api('notifications'));updateBell();}catch{}finally{notificationPolling=false;}},30000);
  load().catch(err=>{notify(err.message,true);content.innerHTML=`<section class="ccs-card"><h1>Não foi possível carregar</h1><p>Confira sua conexão. Se sua sessão expirou, entre novamente.</p>${button('Tentar novamente','refresh')} <a href="${e(CCS_CONFIG.login)}">Entrar novamente</a></section>`;});
})();

